export async function operationProofV64(M,entry,op,role,h){
 if(!names.includes(entry.raw.name)||!JSON.stringify(op).includes('v64')&&!op.kind?.startsWith('spell-')&&op.kind!=='gift-spell-v21'&&!(entry.raw.name==='Undergrowth'&&op.kind==='mechanic-optional-cost-v14')&&!(entry.raw.name==='Bite Down on Crime'&&op.kind==='cost-modifier')&&!(entry.raw.name==='Banish into Fable'&&op.kind==='generic-trigger')&&!(entry.raw.name==='Plunge into Darkness'&&op.kind==='mechanic-entwine')&&!(entry.raw.name==='Savage Order'&&op.kind==='mechanic-additional-costs'))return null;
 let count=0;const assert=Object.fromEntries(['ok','equal','deepEqual','throws','rejects'].map(k=>[k,(...args)=>{count++;return strict[k](...args);} ]));
 for(const positive of[true,false])await proveCommonV64(M,entry.raw.name,role,positive,h,assert);
 return count;
}
